def sunsetViews(heights):
    n = len(heights)
    stack = []
    result = []
    for i in range(n-1, -1, -1):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if not stack:
            result.append(i)
        stack.append(i)
    return result[::-1]

