import math

def least_interval(tasks, n):
    count = {}
    for task in tasks:
        if task not in count:
            count[task] = 0
        count[task] += 1

    max_count = max(count.values())
    max_count_tasks = sum(value == max_count for value in count.values())

    return max((max_count - 1) * (n + 1) + max_count_tasks, len(tasks))

