def shortest_substring(s):
    if not s:
        return ""

    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    unique_chars = len(char_count)
    left = 0
    min_length = float('inf')
    min_substring = ""

    for right in range(len(s)):
        while left <= right and unique_chars > 0:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                unique_chars -= 1
            left += 1

        if unique_chars == 0 and right - left + 1 < min_length:
            min_length = right - left + 1
            min_substring = s[left:right + 1]

        if right < len(s) - 1:
            char_count[s[right]] = char_count.get(s[right], 0) + 1
            if char_count[s[right]] == 1:
                unique_chars += 1

    return min_substring

