import heapq
def min_completion_time(tasks):
    # 优先队列存储任务时间，按从小到大的顺序排列
    pq = []
    for task in tasks:
        # 将每个任务的时间放入优先队列中
        heapq.heappush(pq, task)

    # 两个worker的时间
    worker1_time = 0
    worker2_time = 0

    # 两个worker轮流处理任务，直到所有任务都处理完成
    while pq:
        # worker1处理两个任务
        if len(pq) >= 2:
            worker1_time += sum(heapq.heappop(pq) for _ in range(2))
        # worker1处理最后一个任务
        elif len(pq) == 1:
            worker1_time += heapq.heappop(pq)
        # worker1处理所有任务
        else:
            worker1_time += sum(pq)
            break

        # worker2处理两个任务
        if len(pq) >= 2:
            worker2_time += sum(heapq.heappop(pq) for _ in range(2))
        # worker2处理最后一个任务
        elif len(pq) == 1:
            worker2_time += heapq.heappop(pq)
        # worker2处理所有任务
        else:
            worker2_time += sum(pq)
            break

    # 返回最小完成时间
    return max(worker1_time, worker2_time)

