import numpy as np

def floyd_warshall(adjacency_matrix):
    n = len(adjacency_matrix)

    # Create a copy of the original adjacency matrix to avoid modifying the input data
    shortest_paths = [[val for val in row] for row in adjacency_matrix]

    # Handle float('inf') correctly to represent infinity
    for i in range(n):
        for j in range(n):
            if shortest_paths[i][j] == float('inf'):
                shortest_paths[i][j] = np.inf

    # Apply the Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                shortest_paths[i][j] = min(shortest_paths[i][j], shortest_paths[i][k] + shortest_paths[k][j])

    return shortest_paths

