import os
import unittest

def manipulate_env(action, key, value=None):
    if action == "add" or action == "modify":
        os.environ[key] = value
    elif action == "delete":
        if key in os.environ:
            del os.environ[key]
    elif action == "get":
        return os.environ.get(key, None)

class TestManipulateEnv(unittest.TestCase):
    def test_add_modify(self):
        manipulate_env("add", "TEST_VAR", "test_value")
        self.assertEqual(os.environ["TEST_VAR"], "test_value")
        manipulate_env("modify", "TEST_VAR", "new_value")
        self.assertEqual(os.environ["TEST_VAR"], "new_value")

    def test_delete(self):
        os.environ["TEST_VAR"] = "test_value"
        manipulate_env("delete", "TEST_VAR")
        self.assertNotIn("TEST_VAR", os.environ)

    def test_get(self):
        os.environ["TEST_VAR"] = "test_value"
        self.assertEqual(manipulate_env("get", "TEST_VAR"), "test_value")
        self.assertEqual(manipulate_env("get", "NON_EXISTENT_VAR"), None)

if __name__ == "__main__":
