import collections

class TrieNode:
    def __init__(self):
        self.children = collections.defaultdict(TrieNode)
        self.end_of_word = False

class Solution:
    def findWords(self, s, words):
        root = TrieNode()
        for word in words:
            node = root
            for char in word:
                node = node.children[char]
            node.end_of_word = True

        def dfs(node, path):
            if node.end_of_word:
                result.append(path)
            for char, child_node in node.children.items():
                dfs(child_node, path + char)

        result = []
        dfs(root, s)
        return result

