        return -1

    left, right = 0, len(marks) - 1
    while left <= right:
        mid = (left + right) // 2
        if marks[mid] == target_mark:
            # If the target mark is found, check if it's the first occurrence
            if mid == 0 or marks[mid - 1] != target_mark:
                return mid
            right = mid - 1
        elif marks[mid] < target_mark:
            left = mid + 1
        else:
